import { Component } from '@angular/core';

@Component({
  selector: 'pct-avatar',
  templateUrl: './avatar.html',
  host: {
    '(focus)': '$event.target.tabIndex = rank; $event.stopPropagation()',
  },
})
export class PctAvatar {
  protected readonly rank = 5;
}
